private final ReentrantLock lock = new ReentrantLock();
private final Condition notEmpty = lock.newCondition();
private final Condition notFull  = lock.newCondition();

public int take() throws InterruptedException {
    lock.lock();
    try {
        while (queue.isEmpty()) notEmpty.await();  // only this wait set
        int v = queue.poll(); notFull.signal();    // wake the right producer
        return v;
    } finally { lock.unlock(); }
}

BlockingQueue<Task> q = new ArrayBlockingQueue<>(64);

// consumer thread
for (;;) {
    Task t = q.take();              // waits while the queue is empty
    if (t == POISON) break;         // end-of-stream marker instead of close()
    handle(t);
}

// producer thread
try { q.put(task); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
